"""Tags written inside FLAC files (app.audio.flac_tags). Audio is generated by FFmpeg."""

import hashlib
import json
import shutil
import subprocess
from pathlib import Path

import pytest

from app.audio import flac_tags
from tests.audio_fixtures import FFMPEG, make_audio, requires_ffmpeg

COMMENTS = [
    ("TITLE", "item-1"),
    ("ARTIST", "SPK-AAAAA"),
    ("TRANSCRIPTION", "नदी के किनारे"),
    ("translation_en", "By the river"),
]


def _chunks(content: bytes, size: int = 7) -> list[bytes]:
    """Small pieces, so block headers and bodies fall across chunk boundaries."""
    return [content[i : i + size] for i in range(0, len(content), size)]


def _probe_tags(path: Path) -> dict[str, str]:
    result = subprocess.run(  # noqa: S603 - test helper, fixed program
        [shutil.which("ffprobe") or "ffprobe", "-v", "error", "-of", "json", "-show_format", path],
        check=True,
        capture_output=True,
        timeout=60,
    )
    tags: dict[str, str] = json.loads(result.stdout)["format"].get("tags", {})
    return {key.upper(): value for key, value in tags.items()}


def _pcm_md5(path: Path) -> str:
    result = subprocess.run(  # noqa: S603 - test helper, fixed program
        [FFMPEG, "-v", "error", "-i", path, "-f", "md5", "-"],
        check=True,
        capture_output=True,
        timeout=60,
    )
    return result.stdout.decode().strip()


@requires_ffmpeg
def test_tags_replace_the_old_ones_and_leave_the_audio_unchanged(tmp_path: Path) -> None:
    source = tmp_path / "in.flac"
    make_audio(source, "flac", extra=("-metadata", "artist=Synthetic Speaker Name"))
    content = source.read_bytes()

    out = tmp_path / "out.flac"
    out.write_bytes(b"".join(flac_tags.tagged(_chunks(content), COMMENTS)))

    tags = _probe_tags(out)
    assert tags["TITLE"] == "item-1"
    assert tags["ARTIST"] == "SPK-AAAAA"
    assert tags["TRANSCRIPTION"] == "नदी के किनारे"
    assert tags["TRANSLATION_EN"] == "By the river"
    assert "Synthetic Speaker Name" not in json.dumps(tags, ensure_ascii=False)
    assert _pcm_md5(out) == _pcm_md5(source)
    # The same input and tags always give the same bytes, read in any chunk size.
    again = b"".join(flac_tags.tagged([content], COMMENTS))
    assert hashlib.sha256(again).digest() == hashlib.sha256(out.read_bytes()).digest()


def test_files_that_are_not_flac_are_refused() -> None:
    with pytest.raises(flac_tags.NotFlac):
        list(flac_tags.tagged([b"RIFF" + b"\x00" * 40], COMMENTS))
    with pytest.raises(flac_tags.NotFlac):
        list(flac_tags.tagged([b"fLaC\x80\x00\x00"], COMMENTS))  # ends inside a header


def test_tag_names_must_be_plain_ascii() -> None:
    with pytest.raises(ValueError, match="tag name"):
        flac_tags.comment_block([("A=B", "x")], last=True)
    with pytest.raises(ValueError, match="tag name"):
        flac_tags.comment_block([("नाम", "x")], last=True)
